rates = cells('Effective rates', 'C804:F807')

# tx: [Currency, Source amount, Event date]
# rates: [End, Rate, Currency, Start]

total = 0.0
for row in tx:
    curr, amt, edate = row[0], row[1], row[2]
    # edate is datetime object
    if edate.strftime('%Y-%m-%d') == '2031-01-16':
        applicable_rate = None
        for r in rates:
            rend, rate, rcurr, rstart = r[0], r[1], r[2], r[3]
            if rcurr == curr and rstart <= edate < rend:
                applicable_rate = rate
                break
